# Source-backed context and explicit physical-state consequences, corrections14.
notes['Anti-Matter']=(notes['Anti-Matter'][0]+'; ordinary rulebook attack resolution', notes['Anti-Matter'][1]+' The ordinary defense-wins-ties rule still applies when totals are equal.')
notes['Cudgel']=(notes['Cudgel'][0], notes['Cudgel'][1]+' A successfully made deal is a successful encounter, but is not a win for Cudgel or Barbarian.')
notes['Masochist']=(notes['Masochist'][0]+'; FAQ p5', notes['Masochist'][1]+' This explicitly immediate win ends the game when its effect resolves, without waiting for the end of Resolution, unless zapped or specifically interrupted.')
