notes['Filch']=(notes['Filch'][0]+'; general flare cancellation FAQ p6', notes['Filch'][1].replace('it may then be zapped.', 'the revealed flare may then be Card Zapped.'))

def assemble():
 d=json.loads((R/'source-review/alien-catalog.json').read_text())
 s=(R/'core-repair-draft.md').read_text()+'\n'
 s=s.replace('Resolve actual simultaneous contradictory effects in order:', 'Effects associated with no player resolve last, after the player order. Resolve actual simultaneous contradictory effects in order:')
 s=s.replace('Base card types are', 'Old terminology: challenge means encounter; cone means hyperspace gate. An unqualified deck or discard pile means the cosmic deck or its discard. A legal encounter is one where offense can ultimately gain a foreign colony without having to make a deal.\n\nShips landing on colonies do so simultaneously, including ships released by Mobius Tubes (FAQ p19, general landing rule). With Mobius Tubes and no colony to receive released ships, return those ships to warp; offense may first place up to four of its released ships in the gate.\n\nBase card types are')
 for a in d['aliens']:
  phases=['Destiny'] if a['alien']=='Will' else (['Launch','Alliance','Reveal'] if a['alien']=='Macron' else a['phases'])
  s+='\n#### '+a['alien']+'\n\n**'+a['power']+' — '+a['role']+'; '+a['use'].lower()+'; '+', '.join(phases)+'.**\n\n'
  for x in a['setup']:
   x=x.split('; EIGHT')[0]+'.' if a['alien']=='Tick-Tock' else x
   s+='- Setup: '+x+'\n'
  for x in a['rules']:
   x=x.replace(' In either case add ONE EXTRA if playing four planets per player.','')
   if a['alien']=='Warrior':
    x=x.replace('Add one token each time you win encounter or make deal, TWO each time lose or fail deal.', 'After an encounter in which you were a main player, add one token if you won or made a deal, or two if you lost or failed a deal (retained official FAQ May 6, 2009 p1 erratum).')
   if a['alien']=='Spiff':
    x=x.replace('own total was 10 OR MORE less than defense', 'you lost by 10 OR MORE (retained official FAQ May 6, 2009 p1 erratum, including low-total-wins encounters)')
   if a['alien']=='Macron':
    x=x.replace('As defense or ally use after allies invited.', 'As ally use after allies invited. As main player or ally, use after cards are revealed for the ship-strength effect (retained official FAQ May 6, 2009 p1 erratum).')
   if a['alien']=='Zombie':
    x=x.replace("May free ANY player's ships from warp back to any colonies that player has as part of deal.", "As part of your deal, may free your negotiating opponent's ships from the warp, returning them to any existing colonies that opponent has.")
   s+='- '+x+'\n'
  for x in a.get('restrictions',[]):s+='- Restriction: '+x+'\n'
  if a['alien'] in notes:
   ref,t=notes[a['alien']];s+='\n**'+ref+':** '+t+'\n'
 s+='\n## Player Reference\n\n| Step | Main task |\n|---|---|\n| Start Turn, first encounter only | Replace encounter-less offensive hand before Regroup effects |\n| Regroup | Mandatory one-ship warp retrieval if available |\n| Destiny | Determine defense/system; reshuffle before drawing last card |\n| Launch | Target planet and commit 1–4 offense ships normally |\n| Alliance | Offense invites, defense invites, others commit clockwise |\n| Planning | Main players select encounter cards; respect powers\' before/after timing |\n| Reveal | Reveal pairing, resolve effects and reinforcement responses |\n| Resolution | Ship destinations, compensation/rewards, discards, victory check |\n\nAttack totals include own side\'s ships; defense wins ties. Successful first encounter plus an encounter card in hand permits an optional second. Five current foreign colonies win at the end of Resolution, subject to alternate immediate-win powers. See the specific procedures and alien exceptions above.\n\n## FAQ & Rulings\n\nAuthority: the original2008 CE01 base rules and original fifty printed alien sheets; base-only entries in the official FAQ updated through2018. One claim-specific supplement is adopted from the later revised FFG rulebook p16, Advanced Setup step4: simultaneous chosen-alien reveal after private selection and unused-sheet returns, before deck preparation. This is a later-source operational clarification of the shared procedure, not a claim of retroactive2008 erratum authority. The revised51st alien/flare, Cosmic Combos, Quick-Start components, revised default selection/flaring/first-player procedure and all other revised rules are excluded. Optional Technology/variants and expansion rulings remain excluded. FAQ page references in the alien entries identify corrections and component-specific exceptions; they do not import expansion content. The reinforcement/negotiate wording conflict is explicitly recorded above rather than resolved by an invented rule.\n'
 baseline=(R/'baseline/summary-snapshot.md').read_text();prefix=baseline[:baseline.index('## Overview')]
 prefix=prefix.replace('source_pdf: "cosmic-encounter-rules.pdf"','source_pdf: "cosmic-encounter-2008-rules.pdf"').replace('summarized_date: "2026-03-19"','summarized_date: "2026-11-07"\nrulebook_version: "Fantasy Flight English 2008 CE01, original 50 aliens; base FAQ through 2018; attributed later setup-reveal clarification only"')
 prefix=prefix.replace('designer: \"Bill Eberle, Jack Kittredge, Bill Norton, Peter Olotka, Kevin Wilson\"','designer: \"Bill Eberle, Jack Kittredge, Bill Norton, Peter Olotka\"\ndeveloper: \"Kevin Wilson\"')
 draft='\n'.join(line.rstrip() for line in (prefix+s).splitlines())+'\n'
 (R/'repair-v1.md').write_text(draft)
 (R/'repair-v1.patch').write_text(''.join(difflib.unified_diff(baseline.splitlines(True),draft.splitlines(True),fromfile='baseline',tofile='repair-v1')))
 print('repair-v1 chars',len(draft),'sha256',hashlib.sha256(draft.encode()).hexdigest())
if __name__=='__main__':assemble()
